import{_ as l,a0 as p,w as r,s as o,I as e,x as t,a1 as i,A as n,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在 Linux 上創建一個加密文件保險庫 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上創建一個加密文件保險庫 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上創建一個加密文件保險庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上創建一個加密文件保險庫 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210413 Create an encrypted file vault on Linux","title":"在 Linux 上創建一個加密文件保險庫","tag":"202104","desc":""},"relativePath":"202104/20210413 Create an encrypted file vault on Linux.md","filePath":"[post].md"}'),d={name:"202104/20210413 Create an encrypted file vault on Linux.md"};function h(g,s,k,m,b,f){const a=p("Link");return r(),o("div",null,[s[29]||(s[29]=e("h1",{id:"在-linux-上創建一個加密文件保險庫",tabindex:"-1"},[t("在 Linux 上創建一個加密文件保險庫 "),e("a",{class:"header-anchor",href:"#在-linux-上創建一個加密文件保險庫","aria-label":"Permalink to “在 Linux 上創建一個加密文件保險庫”"},"​")],-1)),s[30]||(s[30]=e("blockquote",null,[e("p",null,"使用 Linux 統一密鑰設置（LUKS）為物理驅動器或雲存儲上的敏感文件創建一個加密保險庫。")],-1)),s[31]||(s[31]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/14/151220l5zkkxiukgzix54k.jpg",alt:""})],-1)),e("p",null,[s[3]||(s[3]=t("最近，我演示瞭如何在 Linux 上使用",-1)),s[4]||(s[4]=e("ruby",null,[t("統一密鑰設置"),e("rt",null,"Linux Unified Key Setup")],-1)),s[5]||(s[5]=t("（",-1)),i(a,{href:"https://gitlab.com/cryptsetup/cryptsetup/blob/master/README.md"},{default:n(()=>[...s[0]||(s[0]=[t("LUKS",-1)])]),_:1}),s[6]||(s[6]=t("）和 ",-1)),s[7]||(s[7]=e("code",null,"cryptsetup",-1)),s[8]||(s[8]=t(" 命令 ",-1)),i(a,{href:"https://opensource.com/article/21/3/encryption-luks"},{default:n(()=>[...s[1]||(s[1]=[t("實現全盤加密",-1)])]),_:1}),s[9]||(s[9]=t("。雖然加密整個硬盤在很多情況下是有用的，但也有一些原因讓你不想對整個硬盤進行加密。例如，你可能需要讓一個硬盤在多個平台上工作，其中一些平台可能沒有集成 ",-1)),i(a,{href:"https://gitlab.com/cryptsetup/cryptsetup/blob/master/README.md"},{default:n(()=>[...s[2]||(s[2]=[t("LUKS",-1)])]),_:1}),s[10]||(s[10]=t("。此外，現在是 21 世紀，由於雲的存在，你可能不會使用物理硬盤來處理所有的數據。",-1))]),e("p",null,[s[12]||(s[12]=t("幾年前，有一個名為 ",-1)),i(a,{href:"https://en.wikipedia.org/wiki/TrueCrypt"},{default:n(()=>[...s[11]||(s[11]=[t("TrueCrypt",-1)])]),_:1}),s[13]||(s[13]=t(" 的系統，允許用户創建加密的文件保險庫，可以通過 TrueCrypt 解密來提供讀/寫訪問。這是一項有用的技術，基本上提供了一個虛擬的便攜式、完全加密的驅動器，你可以在那裏存儲重要數據。TrueCrypt 項目關閉了，但它可以作為一個有趣的模型。",-1))]),s[32]||(s[32]=u(`<p>幸運的是，LUKS 是一個靈活的系統，你可以使用它和 <code>cryptsetup</code> 在一個獨立的文件中創建一個加密保險庫，你可以將其保存在物理驅動器或雲存儲中。</p><p>下面就來介紹一下怎麼做。</p><h3 id="_1、建立一個空文件" tabindex="-1">1、建立一個空文件 <a class="header-anchor" href="#_1、建立一個空文件" aria-label="Permalink to “1、建立一個空文件”">​</a></h3><p>首先，你必須創建一個預定大小的空文件。就像是一種保險庫或保險箱，你可以在其中存儲其他文件。你使用的命令是 <code>util-linux</code> 軟件包中的 <code>fallocate</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fallocate --length 512M vaultfile.img</span></span></code></pre></div><p>這個例子創建了一個 512MB 的文件，但你可以把你的文件做成任何你想要的大小。</p><h3 id="_2、創建一個-luks-卷" tabindex="-1">2、創建一個 LUKS 卷 <a class="header-anchor" href="#_2、創建一個-luks-卷" aria-label="Permalink to “2、創建一個 LUKS 卷”">​</a></h3><p>接下來，在空文件中創建一個 LUKS 卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cryptsetup --verify-passphrase \\</span></span>
<span class="line"><span>    luksFormat vaultfile.img</span></span></code></pre></div><h3 id="_3、打開-luks-卷" tabindex="-1">3、打開 LUKS 卷 <a class="header-anchor" href="#_3、打開-luks-卷" aria-label="Permalink to “3、打開 LUKS 卷”">​</a></h3><p>要想創建一個可以存儲文件的文件系統，必須先打開 LUKS 卷，並將其掛載到電腦上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cryptsetup open \\</span></span>
<span class="line"><span>    --type luks vaultfile.img myvault</span></span>
<span class="line"><span>$ ls /dev/mapper</span></span>
<span class="line"><span>myvault</span></span></code></pre></div><h3 id="_4、建立一個文件系統" tabindex="-1">4、建立一個文件系統 <a class="header-anchor" href="#_4、建立一個文件系統" aria-label="Permalink to “4、建立一個文件系統”">​</a></h3><p>在你打開的保險庫中建立一個文件系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkfs.ext4 -L myvault /dev/mapper/myvault</span></span></code></pre></div><p>如果你現在不需要它做什麼，你可以關閉它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cryptsetup close myvault</span></span></code></pre></div><h3 id="_5、開始使用你的加密保險庫" tabindex="-1">5、開始使用你的加密保險庫 <a class="header-anchor" href="#_5、開始使用你的加密保險庫" aria-label="Permalink to “5、開始使用你的加密保險庫”">​</a></h3><p>現在一切都設置好了，你可以在任何需要存儲或訪問私人數據的時候使用你的加密文件庫。要訪問你的保險庫，必須將其掛載為一個可用的文件系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cryptsetup open \\</span></span>
<span class="line"><span>    --type luks vaultfile.img myvault</span></span>
<span class="line"><span>$ ls /dev/mapper</span></span>
<span class="line"><span>myvault</span></span>
<span class="line"><span>$ sudo mkdir /myvault</span></span>
<span class="line"><span>$ sudo mount /dev/mapper/myvault /myvault</span></span></code></pre></div><p>這個例子用 <code>cryptsetup</code> 打開保險庫，然後把保險庫從 <code>/dev/mapper</code> 下掛載到一個叫 <code>/myvault</code> 的新目錄。和 Linux 上的任何卷一樣，你可以把 LUKS 卷掛載到任何你想掛載的地方，所以除了 <code>/myvault</code>，你可以用 <code>/mnt</code> 或 <code>~/myvault</code> 或任何你喜歡的位置。</p><p>當它被掛載後，你的 LUKS 卷就會被解密。你可以像讀取和寫入文件一樣讀取和寫入它，就像它是一個物理驅動器一樣。</p><p>當使用完你的加密保險庫時，請卸載並關閉它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo umount /myvault</span></span>
<span class="line"><span>$ sudo cryptsetup close myvault</span></span></code></pre></div><h3 id="加密的文件保險庫" tabindex="-1">加密的文件保險庫 <a class="header-anchor" href="#加密的文件保險庫" aria-label="Permalink to “加密的文件保險庫”">​</a></h3><p>你用 LUKS 加密的鏡像文件和其他文件一樣，都是可移動的，因此你可以將你的保險庫存儲在硬盤、外置硬盤，甚至是互聯網上。只要你可以使用 LUKS，就可以解密、掛載和使用它來保證你的數據安全。輕鬆加密，提高數據安全性，不妨一試。</p><hr>`,27)),e("p",null,[s[15]||(s[15]=t("via: ",-1)),i(a,{href:"https://opensource.com/article/21/4/linux-encryption"},{default:n(()=>[...s[14]||(s[14]=[t("https://opensource.com/article/21/4/linux-encryption",-1)])]),_:1})]),e("p",null,[s[20]||(s[20]=t("作者：",-1)),i(a,{href:"https://opensource.com/users/seth"},{default:n(()=>[...s[16]||(s[16]=[t("Seth Kenlon",-1)])]),_:1}),s[21]||(s[21]=t(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[17]||(s[17]=[t("lujun9972",-1)])]),_:1}),s[22]||(s[22]=t(" 譯者：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[18]||(s[18]=[t("wxy",-1)])]),_:1}),s[23]||(s[23]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[19]||(s[19]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[26]||(s[26]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[24]||(s[24]=[t("LCTT",-1)])]),_:1}),s[27]||(s[27]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[25]||(s[25]=[t("Linux中國",-1)])]),_:1}),s[28]||(s[28]=t(" 榮譽推出",-1))])])}const L=l(d,[["render",h]]);export{v as __pageData,L as default};
